/// <summary>
/// Extension of form <c>InventItemOrderSetup</c> datasource <c>InventItemSalesSetup</c>.
/// </summary>
[ExtensionOf(formDataSourceStr(InventItemOrderSetup, InventItemSalesSetup))]
final class METInventItemOrderSetupFormInventItemSalesSetupDS_Extension
{
}

Method.Source:
/// <summary>
/// Activates the form data source.
/// </summary>
/// <returns></returns>
public int active()
{
    int ret = next active();

    SecurityRights securityRights = SecurityRights::construct();

    AccessRight maxAccess = securityRights.formControlAccessRight(formStr(InventItemOrderSetup), formControlStr(InventItemOrderSetup, METSecurityControl));

    if (maxAccess == AccessRight::Edit && this.allowEdit())
    {
        this.disableControls();
    }

    return ret;
}

/// <summary>
/// Disables the specified controls on the form.
/// </summary>
private void disableControls()
{
    FormControl formControl;

    container nonEditableControls =
    [
        formControlStr(InventItemOrderSetup, InventItemSalesSetup_METSalesUnit),
        formControlStr(InventItemOrderSetup, InventItemSalesSetup_METAltSalesUnit),
        formControlStr(InventItemOrderSetup, GUPDiscountClaimVendorAccount),
        formControlStr(InventItemOrderSetup, SalesOtherGrp_M_editLeadTimeSiteSpecific),
        formControlStr(InventItemOrderSetup, SalesOtherGrp_M_editLeadTimeDefault),
        formControlStr(InventItemOrderSetup, SalesDeliveryControlGrp_M_editATPTimeFence),
        formControlStr(InventItemOrderSetup, SalesDeliveryControlGrp_M_editATPApplyDemandTimeFence),
        formControlStr(InventItemOrderSetup, SalesDeliveryControlGrp_M_editDeliveryDateControlType),
        formControlStr(InventItemOrderSetup, SalesDeliveryControlGrp_M_editATPInclPlannedOrders),
        formControlStr(InventItemOrderSetup, SalesDeliveryControlGrp_M_editATPApplySupplyTimeFence),
        formControlStr(InventItemOrderSetup, SalesDeliveryControlGrp_M_editATPBackwardSupplyTimeFence),
        formControlStr(InventItemOrderSetup, SalesDeliveryControlGrp_M_editATPBackwardDemandTimeFence)
    ];

    int i;

    for (i = 1; i <= conLen(nonEditableControls); i++)
    {
        formControl = this.formRun().design().controlName(
        conPeek(nonEditableControls, i));

        if (formControl)
        {
            formControl.allowEdit(false);
        }
    }
}
